import {Chess} from './chess.js';
import {findPuzzle,position} from './academy.js?v=20';

// Original teaching scripts. Coordinates are data for the board, never narration.
const P=(id,moves=[])=>{const g=position(findPuzzle(id));for(const m of moves)g.move({from:m.slice(0,2),to:m.slice(2,4),promotion:m[4]});return g.fen();};
const start=(moves=[])=>{const g=new Chess();for(const m of moves)g.move(m);return g.fen();};
const B=(text,marks=[],arrows=[],move=null,cue=null)=>({text,marks,arrows,move,cue});
const S=(title,fen,beats,flipped=false)=>({title,fen,beats,flipped});
const Q=(question,options,correct,why)=>({question,options,correct,why});
export const deepLessons=[
{id:'captures',title:'Voir le danger avant de chercher le beau coup',subtitle:'Menaces, pièces protégées et échanges : apprendre à regarder.',icon:'◉',category:'Les fondamentaux',theme:'focus-captures',guided:'safe-capture',related:['captures','defense'],
 takeaway:'Avant de jouer : qu’est-ce qu’il menace ? Si je prends, qui reprend ? Après mon coup, mon roi et mes pièces sont-ils en sécurité ?',
 scenes:[
 S('On apprend à regarder ensemble',P('safe-capture'),[
 B('Installe-toi. Dans ce cours, tu n’as aucun coup à deviner. Je vais te montrer comment regarder une position, puis comment comparer deux idées. Le quiz viendra seulement quand nous aurons tout expliqué. Sur cet échiquier, tu joues les blancs, en bas. Regarde ton roi entouré, vers le coin en bas à droite. Les noirs sont en haut. Les cercles et les flèches te montreront toujours de quoi je parle. Tu n’as pas besoin de connaître les noms des cases.',['g1']),
 B('Pour progresser vite, commence par éviter les cadeaux. Une combinaison spectaculaire ne sert pas beaucoup si, juste après, tu laisses ta dame se faire prendre. Regarde les deux pièces blanches entourées en bas : ta dame, avec sa couronne, et ton fou, un peu plus haut à gauche. Elles peuvent toutes les deux prendre quelque chose. Nous allons ralentir juste assez pour voir ce qui se passe après. Ce petit effort change beaucoup de parties entre débutants.',['d1','c2'])]),
 S('Une pièce protégée, ça veut dire quoi ?',P('safe-capture'),[
 B('Regarde la tour noire entourée, presque au milieu. Ta dame peut monter tout droit et la prendre. Tentant, non ? Mais regarde maintenant le petit pion noir juste au-dessus, un peu à droite de cette tour. La flèche montre sa capture en diagonale. Ce pion protège la tour : si une pièce blanche prend sa place, le pion pourra prendre cette pièce blanche. Un défenseur n’est donc pas forcément juste à côté de sa cible, et il n’a pas besoin d’être une grosse pièce.',['d5','e6'],[['e6','d5']]),
 B('Quand je dis « protégée », ne comprends pas « interdite à prendre ». On peut parfois échanger des pièces avantageusement. La vraie question, c’est ce que chacun perd. Pour comparer simplement : un pion vaut environ un point, un cavalier ou un fou trois, une tour cinq, une dame neuf. Ce sont des repères, pas le score officiel de la partie. Le roi n’a pas de prix : s’il est mat, la partie s’arrête, même si tu as gagné toutes les autres pièces.',['d1','d5'])]),
 S('Regardons le piège jusqu’au bout',P('safe-capture'),[
 B('Je vais volontairement jouer l’idée trop rapide. Suis la flèche verticale. Ma dame prend la tour. Pour l’instant, on pourrait se réjouir : une tour gagnée ! Mais c’est maintenant aux noirs. Ne juge jamais ton idée sur cette seule image. Dans ta tête, donne toujours un tour de jeu à l’adversaire. C’est exactement là que se cachent beaucoup de mauvaises surprises.',['d1','d5'],[['d1','d5']],'d1d5','Ma dame prend la tour'),
 B('Regarde le pion noir entouré. Le pion reprend ma dame. Voilà la position réelle après l’échange. J’ai pris une tour, environ cinq points, et perdu ma dame, environ neuf. Sur ces deux coups, cela me coûte quatre points. Je n’ai aucune attaque de mat qui compense ici. L’erreur n’était pas de capturer ; c’était de regarder mon coup sans regarder sa réponse. Nous allons revenir en arrière et chercher une capture qui résiste à cette vérification.',['e6','d5'],[['e6','d5']],'e6d5','Le pion reprend ma dame')]),
 S('La capture qui tient vraiment',P('safe-capture'),[
 B('Nous sommes revenus avant l’échange. Regarde ton fou entouré, près du bas à gauche, puis la dame noire sur le bord gauche. La flèche relie les deux en diagonale. Avant de prendre, cherchons une reprise : aucun pion, cavalier, fou, tour ou roi noir ne peut atteindre la case de cette dame au prochain coup. Cette cible est sans défense. Tu n’as pas besoin d’inventer un piège : une pièce offerte peut déjà suffire à prendre un gros avantage.',['c2','a4'],[['c2','a4']]),
 B('Cette fois, mon fou prend la dame. Tu as gagné la pièce la plus puissante sans donner la tienne. Remarque la méthode : nous avons comparé deux idées, puis imaginé la réponse à chacune. Une dame qui capture n’est pas automatiquement plus forte qu’un fou qui capture. C’est le résultat qui compte. Dans tes parties, quand deux prises t’attirent, fais ce même petit film : je prends, il peut reprendre, qu’est-ce qui reste ?',['c2','a4'],[['c2','a4']],'c2a4','mon fou prend la dame')]),
 S('Avant ton idée, regarde la sienne',P('defense-new'),[
 B('Nouvelle situation. Ici, nous regardons la défense des noirs, qui sont en haut. Le roi noir est entouré, sur sa rangée de départ. La dame blanche, à droite du milieu, vise le pion noir juste devant ce roi et un peu à droite. Le fou blanc vise exactement le même pion en diagonale. Les deux flèches se rejoignent. Cela doit attirer ton regard avant de chercher ton propre plan : deux pièces adverses se concentrent sur un point près de ton roi.',['e8','f7'],[['f3','f7'],['c4','f7']]),
 B('La menace est précise : la dame peut prendre ce pion et faire mat. Le roi ne pourrait pas la capturer, car le fou blanc la protégerait. Sortir une jolie pièce de l’autre côté ne répondrait pas à ce danger. Tu dois donc changer de priorité. Après chaque coup adverse, demande-toi simplement : s’il avait encore le droit de jouer, qu’est-ce qu’il ferait ? Ce n’est pas une question abstraite. Cherche une capture, un échec ou une menace directe comme celle-ci.',['f7','e8'],[['c4','f7']])]),
 S('Défendre peut aussi améliorer ta position',P('defense-new'),[
 B('Regarde le cavalier noir entouré, en haut à droite du roi. Il peut sortir vers le centre et se mettre entre la dame blanche et le pion menacé. Le cavalier coupe la ligne de la dame. La dame ne peut pas sauter par-dessus lui. Tu viens donc de résoudre le problème tout en faisant participer une pièce qui dormait. C’est le genre de coup utile que tu veux chercher : une défense avec une raison claire.',['g8','f6'],[['g8','f6']],'g8f6','Le cavalier coupe la ligne de la dame'),
 B('La partie continue. Tu n’as pas gagné automatiquement, et tu dois regarder le prochain coup blanc. Mais tu n’as pas paniqué devant une dame sortie tôt. Garde quatre idées pour défendre une cible : déplacer la pièce attaquée, ajouter un défenseur, capturer l’attaquant ou couper sa ligne. Toutes ne fonctionnent pas dans chaque position. Ici, bloquer la ligne fonctionne. Si ton roi est en échec, il faut obligatoirement faire disparaître cet échec ; gagner du matériel ailleurs ne suffit pas.',['f6','f7'])]),
 S('Ton petit rituel avant de lâcher la pièce',P('essential-capture-diagonal'),[
 B('Un dernier exemple, avec les blancs. La disposition a changé : ton fou est près de ton roi, en bas à droite. La dame noire est très loin, en haut à gauche. Pourtant, ils sont reliés par une diagonale libre. Ta dame blanche peut aussi prendre une tour au centre, mais un pion noir protège cette tour. Tu reconnais la même idée dans une autre image. C’est cela, apprendre : retrouver une relation entre les pièces, sans mémoriser leur adresse.',['g2','b7','d4','c5'],[['g2','b7'],['c5','d4']]),
 B('Avant chaque coup, fais trois vérifications courtes. D’abord : quel danger vient de créer l’adversaire ? Ensuite : ai-je une capture ou un échec intéressant ? Enfin : après mon coup, que peut-il prendre ou mater ? S’il n’y a ni urgence ni gain clair, améliore une pièce ; nous allons apprendre à le faire dans le cours suivant. Tu peux maintenant répondre au quiz. Puis nous referons une capture ensemble avant de te donner des positions à résoudre seule.',['g1','g2'])])],
 quiz:[Q('Une tour est prenable par ta dame, mais un pion peut reprendre. Que vérifies-tu ?',['Je prends : une tour est forcément un beau cadeau.','Ce que chaque camp perd après la reprise.','Uniquement si mon coup donne échec.'],1,'Après la reprise, tu aurais donné une dame pour une tour : environ neuf points contre cinq. Imagine les deux coups, puis compare.'),Q('L’adversaire menace de te mater au prochain coup. Quelle est ta priorité ?',['Faire disparaître cette menace.','Sortir ma dame pour l’impressionner.','Prendre n’importe quel pion.'],0,'Un mat termine la partie. Tu dois trouver une défense qui fonctionne, sauf si tu peux toi-même terminer la partie immédiatement.'),Q('Une pièce est « protégée ». Cela signifie…',['Qu’elle ne peut jamais être capturée.','Qu’elle est forcément près de son roi.','Qu’une autre pièce peut reprendre un attaquant sur sa case.'],2,'La protection prépare une reprise. Il faut encore vérifier que cette reprise est légale et que l’échange vaut le coup.')]
},
{id:'italian',title:'Bien commencer, sans réciter une ouverture',subtitle:'Le centre, toute ton équipe, puis un plan qui a du sens.',icon:'♘',category:'Les fondamentaux',theme:'focus-italian',guided:'develop-white',related:['italian','center','development','queen-time'],
 takeaway:'Occupe ou contrôle le centre, sors tes cavaliers et tes fous, prépare un abri pour ton roi. Chaque coup doit avoir une raison.',
 scenes:[
 S('À quoi sert une ouverture ?',start(),[
 B('Regarde toute ton équipe, en bas de l’échiquier. Au départ, tes grandes pièces sont rangées derrière les pions. Elles sont puissantes, mais presque aucune ne peut agir loin. L’ouverture, c’est simplement le début de la partie : tu organises ton équipe pour qu’elle puisse jouer. Ton objectif n’est pas de gagner au quatrième coup à chaque fois. C’est d’arriver dans une position où tes pièces travaillent, ton roi est raisonnablement protégé et tu comprends ce que tu veux faire.',['b1','c1','f1','g1']),
 B('Nous allons suivre un début classique avec les blancs. Ne retiens pas une suite de noms de cases. À chaque déplacement, demande-toi ce qui s’améliore. Les noirs ont plusieurs réponses possibles ; nous en montrons une pour comprendre. Si ton ami joue autre chose, tu ne dois pas continuer les yeux fermés. Regarde sa menace, puis retrouve tes trois repères : de la place au milieu, des pièces qui participent, un roi qui ne reste pas exposé sans raison.',['d4','e4','d5','e5'])]),
 S('Le milieu donne des possibilités',start(),[
 B('Les quatre cases entourées au milieu forment le cœur du centre. Une pièce qui agit dans cette zone peut souvent intervenir des deux côtés. Regarde maintenant le pion juste devant ton roi. Je pousse ce pion de deux cases. Il prend de la place et libère un passage en diagonale pour ton fou, celui qui était près du roi. Un seul coup a donc plusieurs effets. Le pion devant la dame est également un bon candidat au premier coup ; ce n’est pas une recette unique.',['e2','d4','e4','d5','e5'],[['e2','e4']],'e2e4','Je pousse ce pion de deux cases'),
 B('Dans notre exemple, les noirs occupent aussi le milieu. Les deux pions se font face. Ils ne peuvent pas se prendre en avançant tout droit : leurs captures sont en diagonale. Surtout, ne confonds pas prendre le centre avec avancer tous tes pions. Chaque coup de pion est un coup où un cavalier ou un fou reste au repos. Tu veux utiliser l’espace que tu viens de créer en faisant sortir des pièces.',['e7','e5'],[['e7','e5']],'e7e5','les noirs occupent aussi le milieu')]),
 S('Sortir une pièce avec une mission',start(['e4','e5']),[
 B('Regarde le cavalier près de ton roi, en bas à droite. Je sors ce cavalier vers le milieu. Il attaque maintenant le pion noir central et influence une autre case du centre. Voilà ce qu’on appelle développer une pièce : la sortir de sa case de départ pour lui donner du travail. Une pièce développée doit être utile et rester en sécurité. Le cavalier de gauche pourrait aussi sortir ; ici nous suivons celui qui prépare le roque du côté du roi.',['g1'],[['g1','f3']],'g1f3','Je sors ce cavalier vers le milieu'),
 B('Les noirs sortent leur cavalier de gauche. Observe la flèche vers leur pion central : ils le défendent tout en faisant participer une nouvelle pièce. Pour les deux camps, la même logique fonctionne. Avant de promener encore le cavalier que tu viens de sortir, regarde ceux qui attendent. Tu n’es pas obligée de rejouer une pièce simplement parce qu’elle a déjà bougé. Mais si elle est attaquée, ou si tu vois un gain concret, tu peux évidemment la déplacer à nouveau.',['b8'],[['b8','c6']],'b8c6','Les noirs sortent leur cavalier de gauche')]),
 S('Deux pièces commencent à travailler ensemble',start(['e4','e5','Nf3','Nc6']),[
 B('Regarde le fou près de ton roi. Le pion central lui a ouvert une diagonale. Je place le fou vers le milieu à gauche. De là, il regarde vers le camp noir, et le passage entre ton roi et la tour de droite est maintenant libre. Ce placement avec le pion central et le cavalier porte le nom de début italien. Le nom est facultatif. Ce qui compte, c’est que tu comprennes pourquoi ces pièces sont sorties.',['f1'],[['f1','c4']],'f1c4','Je place le fou vers le milieu à gauche'),
 B('Les noirs font sortir leur fou à leur tour. Ne te précipite pas sur le pion près du roi adverse simplement parce que ton fou le regarde. Regarder une cible ne prouve pas qu’une capture est bonne. Ton fou peut contrôler cette diagonale et attendre du soutien. Une attaque sérieuse se construit souvent avec plusieurs pièces. Continue à vérifier les menaces, puis pense à ton centre et à la sécurité de ton roi.',['f8'],[['f8','c5']],'f8c5','Les noirs font sortir leur fou à leur tour')]),
 S('Pourquoi la dame ne doit pas tout faire',start(['e4','e5','d4','exd4','Qxd4']),[
 B('Changeons d’exemple pour comprendre une erreur fréquente. Ici, la dame blanche est déjà sortie au milieu après un échange de pions. Regarde le cavalier noir encore en haut à gauche. Le cavalier sort en attaquant la dame. Les noirs font deux choses avec le même coup : ils développent une pièce et menacent ta pièce la plus précieuse. Les blancs doivent tenir compte de cette attaque, alors qu’ils auraient aimé sortir d’autres pièces.',['b8','d4'],[['b8','c6']],'b8c6','Le cavalier sort en attaquant la dame'),
 B('C’est ce qu’on veut dire quand on dit perdre du temps dans l’ouverture. Tu consacres plusieurs tours à sauver la même dame, pendant que l’autre camp fait jouer plusieurs pièces. Sortir la dame tôt n’est pas interdit. Il existe de bonnes raisons de le faire. Mais pour ton plan de base, ne lui demande pas d’attaquer seule. Cherche d’abord un cavalier ou un fou encore au repos, puis une case où il aura une mission.',['c6','d4'],[['c6','d4']])]),
 S('Construire un centre qui tient',start(['e4','e5','Nf3','Nc6','Bc4','Bc5']),[
 B('Revenons à notre début italien. Ton pion central peut avoir besoin de soutien. Je pousse le pion devant la dame d’une case. Il protège maintenant ton pion du milieu, en diagonale. Ce coup libère également ton autre fou. Il ne gagne rien immédiatement, mais il rend ton organisation plus solide. Tu pourrais choisir un plan plus direct dans certaines positions. Ici, nous construisons un plan simple et compréhensible, qui laisse le temps de sortir le reste de ton équipe.',['d2'],[['d2','d3']],'d2d3','Je pousse le pion devant la dame d’une case'),
 B('Le cavalier noir rejoint le centre. Il attaque ton pion central, mais ce pion est maintenant protégé. Tu peux envisager de mettre ton roi à l’abri. Regarde comme les trois idées se complètent : le centre ouvre les pièces, les pièces défendent le centre, et leur sortie prépare le roque. Elles se partagent aussi tes tours de jeu. Pousser encore et encore des pions pendant que le roi reste au milieu peut donc devenir risqué.',['g8'],[['g8','f6']],'g8f6','Le cavalier noir rejoint le centre')]),
 S('Après les premiers coups, un vrai plan',P('italian-center'),[
 B('Nous avançons de quelques coups : ton roi est maintenant en bas à droite, après le roque. Les noirs ont soutenu leur centre. Ton idée suivante peut être de préparer une poussée du pion situé devant ta dame. Regarde le pion blanc entouré sur sa gauche. Ce pion avance d’une case. Il pourra reprendre en diagonale si les noirs échangent au centre. Tu ne pousses donc pas un petit pion au hasard ; tu prépares un changement de position.',['c2','d3'],[['c2','c3']],'c2c3','Ce pion avance d’une case'),
 B('Mais un plan n’est jamais une obligation. Si les noirs créent une menace immédiate, tu dois t’en occuper avant ta poussée. Vérifie aussi ce qui sera échangé et quelles lignes vont s’ouvrir. Tu peux emporter cette méthode dans toutes tes ouvertures : qu’est-ce que mon dernier coup prépare, quelle pièce aide-t-il, et que peut répondre l’adversaire ? Tu n’as pas besoin d’impressionner par une récitation. Des coups simples, reliés entre eux et vérifiés, donnent déjà une vraie impression de maîtrise.',['c3','d4'],[['c3','d4']])])],
 quiz:[Q('Pourquoi avancer un pion central au début ?',['Pour faire automatiquement mat très vite.','Pour gagner de la place et ouvrir le passage aux pièces.','Parce que les pions du bord sont interdits.'],1,'Un pion central peut influencer le milieu et libérer un fou. Il faut ensuite utiliser cet espace en sortant les pièces.'),Q('Que veut dire « développer une pièce » ?',['La sortir sur une case utile où elle peut participer.','La déplacer le plus loin possible.','La jouer trois fois de suite.'],0,'Une pièce développée a du travail : contrôler le centre, défendre une cible ou préparer le roque, sur une case sûre.'),Q('Tu as un plan, mais l’adversaire menace ta dame. Tu…',['Continues le plan sans regarder.','Abandonnes forcément la partie.','Vérifies cette menace avant de poursuivre ton plan.'],2,'Les principes guident tes choix. Une menace concrète peut changer la priorité et justifier de rejouer la même pièce.')]
},
{id:'king-safety',title:'Ton roi : le protéger, puis savoir l’utiliser',subtitle:'Le roque expliqué lentement, les dangers et les exceptions.',icon:'♔',category:'Les fondamentaux',theme:null,guided:'king-shelter',related:['king-safety','mini-castle','king-endgame'],practice:['king-shelter-black','active-king','active-king-black','defense-new','backrank'],
 takeaway:'Au début, cherche un abri sûr. En finale, fais participer le roi si les cases sont sûres. Un roi ne peut jamais entrer dans une attaque.',
 scenes:[
 S('La bonne règle n’est pas « ne jamais bouger »',P('king-shelter'),[
 B('Regarde ton roi entouré, au fond, près du milieu. Il est encore sur sa case de départ. Autour, il reste presque toutes les pièces des deux camps. Dans cette phase, une dame, une tour ou plusieurs pièces peuvent venir l’attaquer. C’est pour cela qu’on évite de promener le roi sans raison au début. Ce n’est pas une interdiction de le déplacer. Tu cherches à lui donner un abri pendant que le reste de ton équipe prend de l’activité.',['e1','e8']),
 B('Le but de l’adversaire n’est pas de capturer physiquement ton roi. Le but est de l’attaquer de façon qu’aucune défense légale ne reste : c’est échec et mat. Si ton roi est attaqué maintenant, on dit seulement échec. Tu dois alors répondre à cette attaque. Tu peux parfois bouger le roi, capturer la pièce qui attaque, ou mettre une pièce entre les deux. Nous allons apprendre un moyen fréquent de préparer sa sécurité avant qu’il y ait urgence : le roque.',['e1'])]),
 S('Le roque, vu pièce par pièce',P('king-shelter'),[
 B('Regarde le roi blanc et la tour du coin droit. Les deux cases entre eux sont vides : le fou et le cavalier sont déjà sortis. Le petit roque est un seul coup qui déplace ces deux pièces. Le roi fait deux pas vers la tour. La tour passe de l’autre côté du roi. Je te montre le roque maintenant. Le roi est derrière ses pions, et la tour est plus proche du centre. Dans les exercices, tu touches le roi, puis sa destination ; l’app déplace la tour avec lui.',['e1','h1','f1','g1'],[['e1','g1'],['h1','f1']],'e1g1','Je te montre le roque maintenant'),
 B('Observe les trois petits pions devant ton roi, en bas à droite. Ils forment un abri qui rend certaines attaques plus difficiles. La tour a aussi gagné un passage vers le milieu. Voilà pourquoi le roque est souvent efficace : tu améliores la sécurité du roi et l’activité d’une tour avec un seul tour de jeu. Mais ce n’est pas un bouclier magique. Si tu avances ensuite tous les pions de cet abri sans raison, tu peux ouvrir des portes à l’adversaire.',['g1','f2','g2','h2','f1'])]),
 S('Quand as-tu le droit de roquer ?',P('king-shelter'),[
 B('Revenons avant le roque. Il y a trois vérifications. Premièrement, le roi et la tour concernée ne doivent jamais avoir bougé. Même s’ils sont revenus sur leur case de départ, le droit est perdu. Deuxièmement, toutes les cases entre les deux doivent être libres. Troisièmement, le roi ne doit ni être en échec, ni traverser une case attaquée, ni arriver sur une case attaquée. Regarde les trois cases entourées : sa case actuelle, son passage et son arrivée.',['e1','f1','g1']),
 B('La tour peut traverser une case attaquée : cette restriction concerne le roi. Et le grand roque existe aussi, de l’autre côté, avec la tour de gauche. Le roi y fait encore deux pas, puis la tour vient à côté de lui. Pour commencer, concentre-toi sur le petit roque montré ici. Tu n’as pas à tout faire à la fois. L’app vérifie la légalité, mais comprendre ces conditions t’évite de découvrir trop tard pourquoi un roque n’est plus possible.',['e1','h1'])]),
 S('Pourquoi un petit pas peut coûter cher',P('king-shelter'),[
 B('Je montre maintenant une autre idée, depuis la même position. Le roi avance simplement d’une case sur sa droite. Ce coup est légal. Il ne perd pas la partie immédiatement. Mais regarde : la tour est toujours dans le coin, et le roi a définitivement perdu son droit de roquer. Tu as consacré un tour à déplacer le roi, sans obtenir les deux améliorations du roque. Dans cette position, il n’y avait pas de menace qui justifiait ce choix.',['e1'],[['e1','f1']],'e1f1','Le roi avance simplement d’une case sur sa droite'),
 B('Retenons la nuance. Si ton roi est en danger et qu’un pas le sauve, fais ce pas. Garder le droit de roquer ne vaut pas plus que sauver la partie. Mais sans urgence, ne bouge pas le roi juste pour passer ton tour ou parce que tu ne vois pas d’attaque. Regarde plutôt tes pièces encore au repos. Un principe utile te dit quoi privilégier ; il ne remplace jamais l’observation de la position réelle.',['f1','h1'])]),
 S('L’abri peut aussi devenir une prison',P('backrank'),[
 B('Nouvel exemple : le roi noir, en haut à droite, est derrière trois pions. Ils le protègent de certaines attaques, mais ils occupent aussi toutes ses cases juste devant lui. Regarde maintenant la tour blanche en bas. La ligne verticale devant elle est libre. Si elle arrive sur la dernière rangée, elle pourra attaquer le roi de côté. Les pions qui semblaient rassurants empêcheraient alors le roi de sortir. Nous étudierons ce mat en détail dans un autre cours.',['g8','f7','g7','h7','d1'],[['d1','d8']]),
 B('Que retenir pour ton propre roi ? Après avoir roqué, continue à regarder les lignes ouvertes, les pièces adverses et les cases de fuite. Parfois, avancer un pion d’une case crée une sortie utile. Parfois, cette poussée affaiblit l’abri et l’autre camp en profite. Tu dois vérifier ce qui arrive juste après. Il n’existe donc pas une règle qui dit de toujours pousser ce pion ou de ne jamais le pousser. La sécurité dépend des attaques possibles, pas seulement de l’apparence du roi.',['g8','g7'])]),
 S('En finale, le roi change de travail',P('active-king'),[
 B('Le décor a changé : il ne reste que les deux rois et un pion blanc. Regarde ton roi en bas, très loin de ton pion au milieu. Aucune dame ni tour ne peut venir l’attaquer. Rester caché au fond ne sert plus à grand-chose. Le roi avance vers son pion. Il commence à rejoindre l’action. En finale, ce roi peut protéger ton pion, attaquer les pions adverses et contrôler leur chemin. Il devient une pièce précieuse pour ton plan.',['e1','e4'],[['e1','e2']],'e1e2','Le roi avance vers son pion'),
 B('Il reste une limite absolue : ton roi ne peut jamais aller sur une case attaquée. L’autre roi contrôle toutes les cases autour de lui ; les deux rois ne peuvent donc jamais se toucher. Les pions adverses attaquent en diagonale, même s’ils semblent petits et inoffensifs. Tu dois vérifier la case d’arrivée avant d’avancer. Activer le roi veut dire le rendre utile en sécurité, pas le lancer vers l’adversaire sans regarder.',['h7','g6','g7','g8','h6','h8'])]),
 S('Une aide concrète au pion',P('active-king',['e1e2','h7g6']),[
 B('Le roi noir s’est rapproché lui aussi. Ton roi blanc est maintenant entouré au-dessous du pion. Le roi se place juste derrière son pion. Regarde les deux pièces blanches : le roi protège directement le pion. S’il arrivait une attaque contre ce pion, il pourrait souvent le défendre ou reprendre une pièce sur sa case. Cette suite illustre le rôle du roi ; elle ne prouve pas que toutes les finales avec un pion de plus sont gagnées.',['e2','e4'],[['e2','e3']],'e2e3','Le roi se place juste derrière son pion'),
 B('Tu peux maintenant remplacer l’ancienne phrase « je bouge le roi seulement en dernier recours » par une règle plus juste. Quand les grosses attaques sont possibles, protège-le et prépare un abri. Quand le danger diminue en finale, demande-toi comment il peut aider. Et à tout moment, respecte les cases attaquées. Nous allons vérifier ces idées avec trois questions, puis tu feras toi-même un roque avant de retrouver le roi dans plusieurs situations différentes.',['e3','e4'],[['e3','e4']])])],
 quiz:[Q('Au début, pourquoi éviter de promener le roi ?',['Parce qu’il n’a pas le droit de bouger.','Parce que beaucoup de pièces peuvent encore l’attaquer.','Parce qu’il doit être capturé en dernier.'],1,'Le roi doit rester hors des attaques. Il a le droit de bouger, et doit parfois le faire, mais un abri est souvent plus utile au début.'),Q('Peux-tu roquer en traversant une case attaquée avec ton roi ?',['Oui, si la tour est protégée.','Oui, si tu ne t’y arrêtes pas.','Non, le passage du roi doit aussi être sûr.'],2,'Le roi ne peut ni partir en échec, ni traverser une attaque, ni arriver en échec pendant un roque.'),Q('Il ne reste que les rois et quelques pions. Quel rôle peut avoir ton roi ?',['Soutenir tes pions et contrôler leur chemin, en sécurité.','Rester obligatoirement dans un coin.','Traverser les cases attaquées pour aller plus vite.'],0,'En finale, le roi participe souvent activement. L’interdiction d’entrer dans une attaque reste toujours valable.')]
},
{id:'forks',title:'La fourchette : deux problèmes en un seul coup',subtitle:'Comprendre le piège, le vérifier, puis encaisser le gain.',icon:'♞',category:'Les tactiques',theme:'focus-forks',guided:'fork-finish',related:['forks'],
 takeaway:'Cherche une case d’où une pièce attaque deux cibles. Vérifie les captures du défenseur. Si tu donnes échec, le roi doit être sauvé avant l’autre cible.',
 scenes:[
 S('Une fourchette, en langage simple',P('fork-finish'),[
 B('Une fourchette, c’est une seule pièce qui attaque deux cibles en même temps. L’adversaire n’a qu’un coup pour répondre, et peut avoir du mal à tout sauver. Regarde la position : ton cavalier blanc est près du milieu, un peu à gauche. Le roi noir est tout en haut à droite, et sa dame est plus à gauche sur la même rangée. Nous allons chercher un saut de cavalier qui menace les deux. Tu n’as rien à trouver pour l’instant ; suis les cercles.',['d5','h7','d7']),
 B('Le cavalier est particulièrement utile pour cela parce qu’il saute par-dessus les pièces et attaque en forme de L. Une fourchette n’est pourtant pas réservée au cavalier. Un pion, un fou, une tour, une dame et même un roi peuvent créer des attaques doubles. Le mot décrit une relation entre les cibles. Pour commencer, nous allons utiliser le roi comme première cible, car cela rend la réponse adverse plus facile à prévoir.',['h7','d7'])]),
 S('Le saut qui crée les deux menaces',P('fork-finish'),[
 B('Regarde la case entourée, au-dessus et à droite de ton cavalier. Depuis cette case, il pourra atteindre le roi noir et la dame noire par deux sauts différents. Ce n’est pas une diagonale de fou : imagine deux petits trajets en L. Je fais sauter le cavalier vers les deux cibles. Maintenant, les deux flèches partent de la même pièce. Le roi est attaqué : c’est échec. La dame est attaquée aussi : voilà notre fourchette.',['d5','f6'],[['d5','f6']],'d5f6','Je fais sauter le cavalier vers les deux cibles'),
 B('Pourquoi l’échec est-il si utile ici ? Parce que les noirs ne peuvent pas simplement sauver leur dame en oubliant leur roi. Ils doivent jouer un coup qui enlève l’échec. Contre un cavalier, mettre une pièce entre le cavalier et le roi ne fonctionne pas : le cavalier saute. Il faut déplacer le roi ou capturer le cavalier. Dans cette position, aucune pièce noire ne peut prendre ce cavalier immédiatement. Le roi doit donc s’écarter.',['f6','h7','d7'],[['f6','h7'],['f6','d7']])]),
 S('Ne t’arrête pas au joli premier coup',P('fork-finish',['d5f6']),[
 B('Voici une réponse possible des noirs. Le roi se décale vers le bas à gauche. Cette fuite enlève l’échec, mais elle ne sauve pas la dame. Regarde ton cavalier et la dame noire restée sur sa rangée. La menace continue d’exister. D’autres fuites du roi sont possibles dans cette position ; nous suivons celle-ci pour voir l’idée jusqu’au bout. En partie, tu dois regarder le coup réellement joué avant de continuer.',['h7'],[['h7','g6']],'h7g6','Le roi se décale vers le bas à gauche'),
 B('À toi maintenant d’encaisser le gain. Le cavalier prend la dame. C’est le deuxième coup blanc qui transforme l’attaque double en avantage concret. Beaucoup de débutants trouvent le premier échec, se réjouissent, puis jouent une autre menace en oubliant le cadeau. Après la réponse au roi, retrouve la seconde cible. Tu n’as pas besoin de faire encore plus spectaculaire : prendre la dame suffit ici. Ensuite, il faudra utiliser ton avantage sans laisser ton roi se faire mater.',['f6','d7'],[['f6','d7']],'f6d7','Le cavalier prend la dame')]),
 S('La question qui évite une fausse combinaison',P('essential-fork-knight'),[
 B('Dans cette nouvelle position, le cavalier blanc est à gauche du milieu. Un pion noir est entouré en haut à droite du centre. Ton cavalier pourrait attaquer la dame en sautant vers le milieu, mais ce pion pourrait alors le prendre. Une attaque sur une grosse pièce ne rend pas ton cavalier invincible. Avant de te lancer, demande-toi : est-ce qu’une pièce adverse peut capturer mon attaquant ? Si oui, calcule le résultat au lieu de supposer que l’autre camp va fuir.',['c4','f6','e5'],[['f6','e5']]),
 B('Regarde plutôt la case entourée plus haut, légèrement à droite du cavalier. De là, il donne échec au roi et attaque la dame. Le cavalier saute sur cette case. Le roi doit répondre. Mais regarde encore les détails : selon sa fuite, il pourrait ensuite reprendre ton cavalier après que tu as pris la dame. Même dans ce cas, échanger un cavalier contre une dame reste ici un gain important. Une combinaison peut être bonne sans que ton attaquant survive jusqu’au bout.',['c4','d6'],[['c4','d6']],'c4d6','Le cavalier saute sur cette case')]),
 S('Un simple pion peut faire la même chose',P('essential-fork-pawn'),[
 B('Changeons de pièce. Le roi noir est en haut à gauche du milieu et sa tour un peu à droite. Tes deux pions blancs sont côte à côte, plus bas. Regarde celui de droite. S’il avance, il pourra attaquer les deux pièces en diagonale. Mais vérifions d’abord sa protection : le pion blanc de gauche contrôle sa case d’arrivée. Le roi noir n’a donc pas le droit de prendre ce pion une fois avancé. Ce détail fait fonctionner l’idée.',['e4','d4','d6','f6'],[['d4','e5']]),
 B('Le pion de droite avance et donne échec. Ses deux diagonales visent le roi et la tour. Le roi doit se sauver, puis le pion pourra prendre la tour après la réponse montrée dans les exercices. Tu vois ce qu’il faut mémoriser : deux cibles atteignables, un attaquant qu’on ne peut pas simplement éliminer, puis une réponse forcée par l’échec. Le nom de la case n’explique rien à lui seul. Les relations entre les pièces expliquent tout.',['e4','e5'],[['e4','e5']],'e4e5','Le pion de droite avance et donne échec')]),
 S('Reconnaître le motif dans tes parties',P('fork-finish'),[
 B('Revenons à notre première image. Quand tu vois deux grosses pièces adverses assez proches, prends le temps de regarder les sauts de ton cavalier. Commence par ceux qui donnent échec : ils limitent souvent les réponses. Tu peux aussi regarder tes pions lorsqu’un roi et une pièce se rapprochent d’eux. Ce sont des indices pour chercher, pas une garantie de gain. Une cible protégée, une capture de ton attaquant ou une menace sur ton propre roi peuvent changer le calcul.',['d5','h7','d7']),
 B('Pour éviter les fourchettes contre toi, fais la même vérification dans l’autre sens. Avant de déplacer ta dame près de ton roi, regarde si un cavalier adverse peut attaquer les deux. Il ne suffit pas que ta case d’arrivée soit libre. Elle doit aussi être sûre après la réponse adverse. Nous allons maintenant vérifier la logique avec un quiz, puis tu feras la fourchette avec mon aide. Ensuite, les positions varieront pour que tu reconnaisses l’idée sans copier exactement l’exemple.',['h7','d7'])])],
 quiz:[Q('Qu’appelle-t-on une fourchette ?',['Deux pièces qui se protègent.','Un seul attaquant qui menace deux cibles à la fois.','Un cavalier qui reste au centre.'],1,'La double menace est l’idée essentielle. Le cavalier est fréquent, mais d’autres pièces et même des pions peuvent faire une fourchette.'),Q('Pourquoi attaquer le roi et la dame est-il particulièrement fort ?',['La dame doit obligatoirement rester immobile.','Le roi peut être sacrifié contre la dame.','L’adversaire doit d’abord faire disparaître l’échec.'],2,'Il ne peut pas ignorer son roi en échec. Vérifie tout de même s’il peut prendre ton attaquant pour résoudre les deux problèmes.'),Q('Avant de jouer la fourchette, quelle défense faut-il vérifier ?',['L’adversaire peut-il capturer mon attaquant ?','La couleur du fond de l’échiquier.','Le nombre de coups déjà joués.'],0,'Un attaquant capturable peut faire échouer le piège. Calcule la réponse et le bilan matériel avant de conclure.')]
},
{id:'pins',title:'Le clouage : quand un défenseur ne peut pas bouger',subtitle:'Voir ce qui se cache derrière une pièce.',icon:'♜',category:'Les tactiques',theme:'focus-pins',guided:'pinned-defender',related:['pins'],
 takeaway:'Regarde les trois pièces alignées : l’attaquant, la pièce au milieu et la cible derrière. Un défenseur cloué au roi ne peut pas ouvrir cette ligne.',
 scenes:[
 S('Une pièce qui fait écran',P('pinned-defender'),[
 B('Regarde les trois pièces entourées sur une même ligne verticale. Tout en bas, ta tour blanche. Plus haut, le cavalier noir. Juste derrière lui, le roi noir. La tour ne peut pas sauter par-dessus le cavalier ; pour l’instant, celui-ci fait écran. Mais si le cavalier quitte cette ligne, la tour regarde directement le roi. Un joueur n’a pas le droit de jouer un coup qui laisse son propre roi en échec. Ce cavalier ne peut donc pas s’écarter.',['e1','e7','e8'],[['e1','e8']]),
 B('On dit qu’il est cloué au roi. Imagine une pièce chargée de tenir une porte fermée : tant qu’elle est là, le danger reste derrière la porte. Si elle s’en va, elle expose le roi. Le mot clouage ne veut pas dire que la pièce est collée pour toujours. Le roi pourrait se déplacer plus tard, une autre pièce pourrait faire écran, ou l’attaquant pourrait disparaître. Ce qui compte, c’est la position maintenant, au moment où tu veux agir.',['e7','e8'])]),
 S('Protégé sur le papier, mais pas dans les faits',P('pinned-defender'),[
 B('Regarde le petit pion noir entouré, légèrement à gauche du milieu. Ta dame blanche, en bas, peut le prendre en montant tout droit. Au premier regard, tu pourrais refuser : le cavalier noir attaque la case de ce pion et semble donc pouvoir reprendre ta dame. C’est une bonne habitude de chercher le défenseur. Il manque juste une deuxième question : ce défenseur a-t-il vraiment le droit de jouer la reprise ?',['d1','d5','e7'],[['e7','d5']]),
 B('Reviens à la ligne de la tour. Si le cavalier capturait ta dame sur la case du pion, il quitterait la ligne qui protège son roi. Son roi serait alors attaqué par ta tour. Cette reprise est illégale. Nous n’espérons pas que l’adversaire oublie de reprendre ; il n’a pas le droit de le faire. Voilà comment un clouage peut rendre une capture possible, même quand une pièce adverse semble défendre la cible.',['e1','e7','e8'],[['e1','e8']])]),
 S('Utiliser le clouage pour gagner quelque chose',P('pinned-defender'),[
 B('Maintenant que nous avons vérifié la reprise, ma dame prend le pion. La dame est proche du cavalier, mais ce cavalier reste devant son roi. Aucune autre pièce noire ne peut reprendre la dame immédiatement dans cet exemple. Tu viens de gagner un pion. Ce n’est pas une victoire automatique, mais un petit avantage concret et sûr. Les bons coups ne sont pas toujours des sacrifices de dame ; savoir prendre un pion qu’on croyait protégé peut déjà faire la différence.',['d1','d5'],[['d1','d5']],'d1d5','ma dame prend le pion'),
 B('Observe que nous avons utilisé deux pièces blanches avec deux rôles différents. La tour immobilise le défenseur. La dame profite de cette immobilisation. C’est une coopération. Si tu déplaçais la tour loin de cette ligne sans réfléchir, tu pourrais rendre sa liberté au cavalier. Dans tes parties, avant de bouger la pièce qui cloue, demande-toi ce qu’elle empêchait. Une protection et une menace peuvent dépendre d’une pièce située très loin de l’action visible.',['e1','e7','d5'])]),
 S('Le même mécanisme en diagonale',P('essential-pin-diagonal'),[
 B('Nouvelle image. Ton fou blanc, à gauche du milieu, vise en diagonale le roi noir tout en haut à droite. Un cavalier noir se trouve entre eux. Regarde la longue flèche : le fou, le cavalier et le roi sont alignés. Le mécanisme est le même qu’avec la tour, mais la ligne est inclinée. Ton autre fou blanc, plus à droite, regarde un pion noir sur le bord. Le cavalier semble protéger ce pion.',['c4','f7','g8','g5','h6'],[['c4','g8']]),
 B('Le fou de droite prend le pion du bord. Le cavalier noir ne peut pas reprendre : il ouvrirait la diagonale de l’autre fou contre son propre roi. Tu n’as pas mémorisé un dessin vertical ; tu as reconnu une relation de trois pièces. C’est ce que nous voulons entraîner. Quand la position change de couleur ou de côté, recherche toujours l’attaquant à longue portée, la pièce qui fait écran et la cible derrière.',['g5','h6'],[['g5','h6']],'g5h6','Le fou de droite prend le pion du bord')]),
 S('Attention : tous les clouages ne sont pas identiques',P('pinned-defender'),[
 B('Ici, la cible cachée derrière le cavalier est le roi. C’est pour cela que quitter la ligne est interdit. Si la pièce derrière était une dame ou une tour, le défenseur aurait le droit de bouger. Il risquerait de perdre la grosse pièce derrière, mais un autre gain pourrait parfois le justifier. On parle alors d’un clouage relatif. Pour ton niveau, retiens surtout la distinction : le roi impose une règle de légalité ; les autres pièces imposent un calcul.',['e8','e7']),
 B('Autre nuance : une pièce clouée n’est pas toujours incapable de tout mouvement. Une tour clouée sur une colonne pourrait parfois avancer sur cette même colonne tout en continuant à faire écran, ou prendre l’attaquant. Notre cavalier, lui, ne peut pas rester sur la même ligne avec un saut. Évite donc la phrase trop générale « une pièce clouée ne bouge jamais ». Dis plutôt : elle ne peut pas ouvrir la ligne contre son roi. Puis vérifie les coups possibles.',['e1','e7','e8'])]),
 S('Le réflexe à retrouver sans aide',P('essential-pin-file'),[
 B('Un dernier placement : ta tour est en bas à gauche, le roi noir tout en haut de la même colonne, et un cavalier noir fait écran entre les deux. Ton fou, à droite du milieu, regarde un pion noir plus haut. Le cavalier attaque ce pion, mais il ne peut pas quitter la colonne. Tu peux donc comparer cette capture avec plus de confiance. La première étape est toujours de repérer l’alignement, avant de te demander comment en profiter.',['c1','c7','c8','g4','e6'],[['c1','c8'],['g4','e6']]),
 B('Dans tes propres positions, surveille aussi tes pièces alignées devant ton roi. Si un cavalier doit tout défendre mais qu’il est cloué, tes autres pièces sont peut-être moins bien protégées que tu ne le crois. Tu peux envisager de mettre un autre écran, de chasser l’attaquant ou de déplacer le roi en sécurité. Nous allons d’abord vérifier que tu sais expliquer le mécanisme. Puis le premier exercice te guidera avec des cercles et une flèche, avant les problèmes où tu devras le retrouver.',['c7','c8'])])],
 quiz:[Q('Pourquoi le cavalier cloué au roi ne peut-il pas reprendre ?',['Parce qu’un cavalier ne capture pas les dames.','Parce qu’il est trop loin de sa case de départ.','Parce qu’il exposerait son roi à une attaque.'],2,'Un coup qui laisse son propre roi en échec est illégal. C’est ce qui rend le défenseur indisponible dans notre exemple.'),Q('Quelles pièces faut-il repérer pour comprendre un clouage ?',['L’attaquant, la pièce qui fait écran et la cible derrière.','Uniquement les deux rois.','Toutes les pièces de la même couleur de case.'],0,'Ce trio peut être aligné verticalement, horizontalement ou en diagonale, selon l’attaquant.'),Q('Si la cible derrière le défenseur est une dame plutôt qu’un roi…',['Le défenseur n’a toujours jamais le droit de bouger.','Il peut bouger légalement, mais il faut calculer la perte éventuelle de la dame.','Le clouage fait immédiatement mat.'],1,'La dame n’impose pas la même interdiction que le roi. Le déplacement peut être coûteux, mais il reste légal.')]
},
{id:'mates',title:'Faire mat : fermer toutes les portes',subtitle:'Le mat du couloir et la coopération de la dame avec le roi.',icon:'♚',category:'Les tactiques',theme:'focus-mates',guided:'backrank',related:['mates','finish','mini-ladder'],
 takeaway:'Pour vérifier un mat : le roi est-il attaqué ? Peut-il fuir, prendre l’attaquant ou bloquer la ligne ? Sans échec, une absence de coups légaux peut être un pat.',
 scenes:[
 S('Échec ne veut pas encore dire mat',P('backrank'),[
 B('On peut donner beaucoup d’échecs sans gagner. Faire échec, c’est attaquer le roi maintenant. Faire mat, c’est l’attaquer sans lui laisser aucune défense légale. Nous allons donc regarder les portes de sortie, et pas seulement trouver un coup qui fait du bruit. Sur cette position, le roi noir est dans le coin en haut à droite, derrière trois pions. Ta tour blanche est tout en bas, un peu à gauche du milieu. La ligne devant elle est vide.',['g8','d1']),
 B('Quand un roi est en échec, son camp peut essayer trois familles de réponses : déplacer le roi sur une case sûre, prendre la pièce qui attaque, ou bloquer sa ligne avec une pièce. Le blocage ne marche pas contre une attaque de cavalier ou une attaque de très près sans case intermédiaire. Tu n’as pas besoin de réciter ces mots à toute vitesse. Prends chaque possibilité, une par une. C’est plus fiable que de te dire que le roi a l’air coincé.',['g8','f8','h8'])]),
 S('Les pions ferment les portes de devant',P('backrank'),[
 B('Regarde les trois pions noirs juste devant leur roi. Ils occupent les trois cases vers lesquelles le roi pourrait descendre. Un roi ne peut pas aller sur une case occupée par une pièce de son camp. À gauche et à droite, il lui reste des cases sur sa rangée. Notre idée est donc de contrôler cette rangée avec la tour. Les pions bloquent les portes de devant ; la tour va fermer les portes sur les côtés.',['f7','g7','h7','f8','h8']),
 B('Suis la flèche verticale depuis ta tour. La tour monte au fond du camp noir. Elle attaque maintenant le roi en ligne droite, sur la dernière rangée. Elle contrôle aussi les cases sur lesquelles il voudrait se décaler. Le roi est bien en échec. Maintenant, nous allons vérifier les défenses au lieu de conclure trop vite. Ce motif s’appelle le mat du couloir : le roi est enfermé dans une rangée par ses propres pions et par la pièce qui attaque.',['d1','d8'],[['d1','d8']],'d1d8','La tour monte au fond du camp noir')]),
 S('La preuve du mat, pas une impression',P('backrank',['d1d8']),[
 B('Première question : le roi peut-il fuir ? Les cases à gauche et à droite sont attaquées par la tour. Les trois cases devant lui sont occupées par ses propres pions. Il ne peut pas sortir de l’échiquier par le haut. Deuxième question : peut-on prendre notre tour ? Le roi est trop loin, et les pions ne peuvent pas capturer une pièce située derrière eux sur cette rangée. Dans cette position simplifiée, il n’y a pas d’autre pièce noire pour la prendre.',['g8','f8','h8','f7','g7','h7'],[['d8','h8']]),
 B('Troisième question : peut-on mettre une pièce entre la tour et le roi ? Les noirs n’ont ici aucune pièce capable de venir sur les cases entre les deux. Les pions avancent vers le bas, pas vers leur propre rangée du fond. Aucune des trois défenses ne fonctionne. C’est donc bien mat, et la partie est terminée. Le même coup de tour ne serait pas forcément mat si un fou pouvait bloquer la ligne ou si le roi avait une sortie sûre.',['e8','f8','g8'])]),
 S('Une dame peut utiliser le même couloir',P('essential-mate-queen'),[
 B('Nous changeons de position. Ta dame est en bas, proche du milieu, et le roi noir est encore derrière ses trois pions en haut à droite. D’autres pièces sont présentes : ce n’est plus le petit dessin vide. Regarde le passage vertical devant la dame. La dame rejoint la rangée du roi. Elle attaque horizontalement comme une tour. Le motif du couloir peut donc être réalisé par une tour ou une dame, si le chemin est libre et les défenses sont insuffisantes.',['e2','e8'],[['e2','e8']],'e2e8','La dame rejoint la rangée du roi'),
 B('Cette fois encore, il faut vérifier les pièces restantes. La tour noire, sur la gauche, ne peut pas capturer notre dame ni se placer entre elle et le roi. Le fou noir ne peut pas non plus bloquer cette ligne. Les pions du roi ferment toujours ses sorties. Ce contrôle est essentiel : reconnaître un dessin te donne une idée, mais seule l’analyse des réponses te permet de dire « c’est mat ». Tu vas t’entraîner à faire les deux.',['b6','c8','f8','g8'])]),
 S('Quand la dame s’approche, elle a besoin d’aide',P('queen-mate'),[
 B('Regarde cette finale : le roi noir est dans le coin supérieur droit. Ta dame blanche est juste en dessous et à gauche, et ton roi blanc se trouve à côté d’elle. La dame peut venir tout près du roi noir pour fermer ses sorties. Mais elle ne doit pas s’offrir gratuitement. Regarde la case entourée au-dessus de la dame : ton roi blanc protège cette case en diagonale. C’est la coopération entre ton roi et ta dame qui rend l’approche sûre.',['f6','g6','g7','h8'],[['f6','g7']]),
 B('La dame monte d’une case près du roi noir. Elle donne échec et contrôle ses sorties. Le roi noir voudrait prendre la dame, mais la case de la dame est protégée par ton roi. Ce serait entrer dans une attaque, donc c’est interdit. Cette fois, ton roi aide directement à faire mat. Tu vois pourquoi on ne peut pas dire que le roi ne sert qu’à se cacher. Son rôle dépend des pièces qui restent et des dangers de la position.',['g6','g7'],[['g6','g7']],'g6g7','La dame monte d’une case près du roi noir')]),
 S('Le piège du pat',P('avoid-stalemate'),[
 B('Un autre exemple de finale. Ton pion blanc est tout près de la dernière rangée, ton roi le soutient et le roi noir est sur le bord gauche. Tu pourrais être tentée de choisir automatiquement une dame en faisant la promotion. Je transforme le pion en dame. Regarde le roi noir : il n’est pas attaqué. Pourtant, il n’a plus de case légale, et il n’a aucune autre pièce à jouer. Ce n’est pas un mat : c’est un pat, donc une partie nulle.',['c7','a7'],[['c7','c8']],'c7c8q','Je transforme le pion en dame'),
 B('La distinction est simple et très importante. Roi attaqué, aucune défense : mat. Roi non attaqué, aucun coup légal pour son camp : pat. Avec un gros avantage, ne ferme pas toutes les sorties sans vérifier l’échec. Dans cette position, une promotion en tour aurait laissé une case au roi et conservé une finale gagnante. Tu n’as pas à apprendre toutes les promotions maintenant ; retiens qu’une pièce plus puissante n’est pas automatiquement le meilleur choix si elle provoque le pat.',['a7','a6','a8','b6','b7','b8'])]),
 S('Ce que tu dois voir avant de dire « mat »',P('backrank'),[
 B('Reprenons le motif du couloir une dernière fois. Les pions noirs bloquent leur roi, la ligne de ta tour est libre, et aucune défense ne peut interrompre son attaque après son arrivée. Dans tes parties, ces trois indices peuvent t’alerter. Mais surveille aussi ton propre roi : s’il est enfermé derrière ses pions, une tour adverse pourrait avoir la même idée. Avant de gagner un pion à l’autre bout du plateau, vérifie que tu n’offres pas ce mat à ton adversaire.',['g8','f7','g7','h7','d1'],[['d1','d8']]),
 B('Tu as maintenant une méthode pour finir une attaque. Cherche un échec, puis fais le tour des défenses : fuite, capture, blocage. Si l’une fonctionne, la partie continue ; il faut chercher mieux ou améliorer ta position. Si aucune ne fonctionne, tu as le mat. Le quiz va tester cette logique. Ensuite, nous ferons le premier mat ensemble, puis plusieurs positions te demanderont de reconnaître le motif avec d’autres pièces et parfois avec les noirs.',['g8'])])],
 quiz:[Q('Quelle différence entre échec et mat ?',['Un mat est un échec auquel aucune défense légale ne répond.','Un mat est un échec donné par une dame.','Un mat exige de capturer le roi.'],0,'Le roi reste sur l’échiquier. La partie s’arrête parce qu’aucun coup légal ne le sauve.'),Q('Le roi n’est pas attaqué, mais son camp n’a aucun coup légal. C’est…',['Une victoire automatique du camp le plus fort.','Un pat : la partie est nulle.','Un échec et mat.'],1,'Pour parler de mat, le roi doit être en échec. Sans échec et sans aucun coup légal, c’est le pat.'),Q('Quelles défenses vérifies-tu avant d’annoncer mat ?',['Seulement les captures de pions.','Seulement les cases devant le roi.','Les fuites du roi, les captures de l’attaquant et les blocages possibles.'],2,'Une seule défense légale suffit à montrer que le roi n’est pas mat. Vérifie les trois familles, selon le type d’attaque.')]
},
{id:'active-piece',title:'Trouver un plan et garder ton avantage',subtitle:'Que jouer quand il n’y a pas de combinaison évidente ?',icon:'♖',category:'Les fondamentaux',theme:null,guided:'open-file',related:['active-piece','endings','mini-open-file','mini-promotion'],practice:['active-rook-new','active-king','active-king-black','queen-mate','avoid-stalemate'],
 takeaway:'Après les urgences, améliore ta pièce la moins utile. Avec de l’avance, reste attentive aux menaces, échange seulement si le résultat t’aide et évite le pat.',
 scenes:[
 S('Tu n’as pas besoin d’un piège à chaque coup',P('open-file'),[
 B('Il y aura des moments où tu ne verras ni fourchette ni mat. Ce n’est pas un échec de ta réflexion. Beaucoup de bons coups préparent quelque chose au lieu de gagner immédiatement. Regarde cette position calme : ton roi blanc est en bas à droite, ton cavalier est sorti, mais ta tour est coincée sur le bord gauche derrière son propre pion. Avant d’inventer une attaque, demande-toi quelle pièce de ton équipe fait le moins de travail.',['a1','a2','c3']),
 B('Cette question vient après la sécurité. Si l’adversaire menace ton roi ou une grosse pièce, réponds d’abord à cela. Sinon, cherche une pièce peu utile et une case où elle pourrait défendre, contrôler une ligne ou viser une faiblesse. Tu n’as pas besoin de déplacer celle qui est déjà la mieux placée. Améliorer la pièce la plus inactive donne souvent un plan simple, concret, et plus solide qu’une poussée de pion choisie parce qu’on ne sait pas quoi faire.',['a1'])]),
 S('Une autoroute pour la tour',P('open-file'),[
 B('Regarde la ligne verticale entourée près du milieu, sur la droite de ton cavalier. Aucun pion ne se trouve sur cette ligne, du bas jusqu’en haut. On appelle cela une colonne ouverte. Le mot colonne veut simplement dire une ligne verticale de cases. Une tour aime ces lignes parce qu’elle peut y agir loin. Sur le bord gauche, son propre pion coupe sa route. Sur la colonne libre, elle aura davantage de possibilités.',['e1','e2','e3','e4','e5','e6','e7','e8'],[['e1','e8']]),
 B('La tour glisse vers la colonne libre. Elle reste sur ta rangée du fond, mais elle regarde maintenant vers le camp adverse. Ce déplacement ne gagne pas une pièce immédiatement. Il améliore ton activité : ton équipe dispose de plus d’options pour la suite. Regarde toujours si la case d’arrivée est sûre et si la tour abandonne une défense importante. « Plus active » n’est pas synonyme de « impossible à capturer ». Un bon plan doit aussi passer le contrôle de sécurité.',['a1','e1'],[['a1','e1']],'a1e1','La tour glisse vers la colonne libre')]),
 S('Un plan, c’est un objectif avec une raison',P('active-rook-new'),[
 B('Voici une autre position : cette fois, ta tour est tout en bas à droite et ton roi à gauche. La ligne libre est plus près du centre gauche. Le dessin a changé, mais la question reste la même : quelle ligne permettra à ma tour de travailler ? Je déplace la tour vers le passage ouvert. Tu reconnais une idée au lieu de répéter le même trajet. Ce savoir se transfère beaucoup mieux à une vraie partie contre tes proches.',['h1','d1'],[['h1','d1']],'h1d1','Je déplace la tour vers le passage ouvert'),
 B('Un plan peut aussi être de défendre un pion faible, de rapprocher le roi en finale ou de préparer une poussée centrale. Tu dois pouvoir le dire avec une phrase simple : « je veux que cette pièce participe ici ». Puis tu regardes la réponse adverse. Si l’autre camp ferme la ligne ou crée un danger plus urgent, adapte ton plan. Les échecs ne sont pas une liste de consignes que l’on suit pendant que l’adversaire attend gentiment.',['d1'],[['d1','d8']])]),
 S('Quand tu as gagné du matériel',P('safe-capture',['c2a4']),[
 B('Nous retrouvons la position après que ton fou a pris la dame noire. Tu as un gros avantage matériel. L’erreur serait de vouloir gagner encore plus vite en donnant tout sans calcul. L’adversaire peut encore tendre un piège ou créer une attaque contre ton roi. Ton premier objectif est de conserver la sécurité de tes pièces et de ton roi. Puis tu utilises ton équipe plus forte pour limiter ses possibilités et préparer une suite claire.',['a4','d1','g1']),
 B('Tu entendras souvent « quand on a de l’avance, il faut échanger ». C’est un repère, pas un ordre. Un échange égal de pièces peut réduire les possibilités d’attaque adverse tout en conservant ton avantage. Mais donner ta dame pour une tour n’est pas un échange égal. Échanger tous les pions peut aussi supprimer tes chances de promotion dans certaines finales. Regarde le résultat exact : qu’est-ce qui reste, mon roi est-il sûr, et ai-je encore un moyen de gagner ?',['d1','d5'])]),
 S('En finale, apporte une pièce de plus : ton roi',P('active-king'),[
 B('Il ne reste ici que les rois et ton pion. Ton roi est très loin derrière. Aucun échange magique ne fera avancer ce pion en sécurité si tu laisses son principal soutien au fond. Ton roi fait un pas vers le pion. En finale, il peut protéger, attaquer des pions et contrôler les cases importantes. Le roi devient une pièce active parce que les grosses menaces ont disparu, pas parce qu’il a soudain le droit d’entrer dans une attaque.',['e1','e4'],[['e1','e2']],'e1e2','Ton roi fait un pas vers le pion'),
 B('Imagine ton plan en mots simples : rapprocher le roi, protéger le pion, puis avancer quand les cases sont sûres. Ce n’est pas une promesse de victoire dans toutes les positions. La distance des rois et les cases contrôlées peuvent tout changer. Pour commencer, retiens que pousser le pion seul à toute vitesse peut le perdre. Parfois, le coup patient avec le roi prépare bien mieux la suite qu’une poussée immédiate.',['e2','e4','h7'])]),
 S('Ne gâche pas l’avance avec un pat',P('avoid-stalemate'),[
 B('Le pion blanc entouré est à un pas de la promotion, tout en haut. Si tu choisis une dame ici, le roi noir ne sera pas en échec mais n’aura aucun coup légal. Ce serait pat, donc nul. On peut avoir une énorme puissance et ne pas gagner si on ferme les mauvaises portes. Regarde une autre possibilité. Le pion se transforme en tour. La tour laisse au roi noir une case de fuite vers le bas, alors que la dame l’aurait aussi contrôlée en diagonale.',['c7','c8','a6'],[['c7','c8']],'c7c8r','Le pion se transforme en tour'),
 B('Nous conservons ainsi une finale gagnante avec un roi et une tour contre un roi, à condition de savoir la jouer. Tu n’as pas fait mat tout de suite. Tu as simplement évité de transformer ton avantage en partie nulle. Avant chaque coup quand l’adversaire a très peu de pièces, vérifie : est-il en échec, et quels coups pourra-t-il jouer ? C’est une vérification très courte qui peut sauver beaucoup de victoires déjà presque acquises.',['a7','a6'])]),
 S('Comment travailler après une partie',P('open-file'),[
 B('Pour progresser entre deux séances, rejoue une partie lente et cherche le premier moment où ton idée a cessé de fonctionner. Ne note pas seulement « j’ai perdu ». Cherche une cause que tu peux travailler : une pièce laissée sans défense, une menace ignorée, un roi resté exposé ou une attaque lancée avec une seule pièce. L’app garde tes erreurs d’exercices pour te les représenter. En partie, cette petite enquête t’aide à choisir la prochaine leçon utile.',['a1','g1']),
 B('Ton objectif n’est pas de te souvenir de toutes les phrases du coach. C’est de retrouver une routine devant une nouvelle position. D’abord le danger adverse. Ensuite mes possibilités concrètes. Enfin sa réponse à mon idée. S’il n’y a rien de forcé, améliore une pièce. Avec de l’avance, reste rigoureuse jusqu’au bout. Nous allons vérifier ces principes, pratiquer une amélioration de tour ensemble, puis te proposer des situations où l’activité et la précision comptent plus qu’un effet spectaculaire.',['a1','e1'],[['a1','e1']])])],
 quiz:[Q('Aucune menace urgente ni capture convaincante. Que peux-tu chercher ?',['Une pièce peu active à améliorer sur une case sûre.','Un sacrifice sans calcul.','Une sortie de roi au hasard.'],0,'Les bons coups ne gagnent pas tous immédiatement. Améliorer une pièce prépare de nouvelles possibilités.'),Q('Tu as une pièce de plus. Faut-il accepter tous les échanges ?',['Oui, sans regarder ce qui reste.','Non, il faut vérifier le bilan, la sécurité et les possibilités de gagner.','Non, aucun échange n’est jamais bon.'],1,'Réduire les attaques adverses peut aider, mais certains échanges perdent du matériel ou suppriment les chances de victoire.'),Q('Que chercher après une défaite pour progresser ?',['Une ouverture secrète à réciter.','Le dernier coup uniquement.','Une erreur concrète qui revient et la leçon pour la corriger.'],2,'Identifier une cause précise permet de travailler le bon réflexe : reprise oubliée, menace ignorée, mauvaise sécurité du roi…')]
},
];

export const deepLessonFor=id=>deepLessons.find(c=>c.id===id||c.related.includes(id));
export const sceneText=s=>s.beats.map(b=>b.text).join(' ');
export function sceneFrames(s){const g=new Chess(s.fen);return s.beats.map(b=>{const before=g.fen();if(b.move)g.move({from:b.move.slice(0,2),to:b.move.slice(2,4),promotion:b.move[4]});return {before,after:g.fen(),...b};});}
